// Accessible app-owned pickers. Native fields remain the source of form data.
const chevron='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m8 10 4 4 4-4"/></svg>';
const calendarIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="4" y="5" width="16" height="16" rx="4"/><path d="M8 3v4m8-4v4M4 11h16"/></svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let active=null,count=0;
const localKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parse=s=>new Date(`${s}T12:00:00`);
const labelFor=el=>el.closest('label')?.childNodes?.[0]?.textContent?.trim()||el.getAttribute('aria-label')||'Seçim';
export function refreshControls(){document.querySelectorAll('.app-control').forEach(w=>{const el=w._field,b=w.querySelector('.control-trigger');if(!el||!b)return;if(b.disabled!==el.disabled)b.disabled=el.disabled;if(el.tagName==='SELECT'){b.querySelector('.control-value').textContent=el.selectedOptions[0]?.textContent||'Seç';}else{const value=el.value;b.querySelector('.control-value').textContent=value?new Intl.DateTimeFormat('tr-TR',matchMedia('(max-width:480px)').matches?(parse(value).getFullYear()===new Date().getFullYear()?{day:'numeric',month:'short'}:{day:'2-digit',month:'2-digit',year:'2-digit'}):{day:'numeric',month:'short',year:'numeric'}).format(parse(value)):'Tarih seç';b.classList.toggle('placeholder',!value);b.title=value?new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}).format(parse(value)):'';}});}
export function closePicker(restore=false){if(!active)return;const {panel,trigger}=active;panel.remove();trigger.setAttribute('aria-expanded','false');active=null;if(restore)trigger.focus();}
function place(panel,trigger){const r=trigger.getBoundingClientRect(),vw=window.innerWidth,vh=window.visualViewport?.height||window.innerHeight;const width=Math.min(Math.max(r.width, panel.classList.contains('calendar-popover')?304:240),vw-24);panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(r.left,vw-width-12))+'px';const availableBelow=vh-r.bottom-12;panel.style.maxHeight=Math.min(panel.classList.contains('calendar-popover')?430:340,Math.max(180,vh-32))+'px';const h=panel.getBoundingClientRect().height;panel.style.top=(availableBelow>=h? r.bottom+7:Math.max(12,r.top-h-7))+'px';}
function choose(field,value,trigger){field.value=value;field.dispatchEvent(new Event('input',{bubbles:true}));field.dispatchEvent(new Event('change',{bubbles:true}));refreshControls();closePicker();trigger.focus();}
function showOptions(field,trigger){closePicker();const panel=document.createElement('div');panel.className='picker-popover select-popover';panel.id=trigger.getAttribute('aria-controls');panel.setAttribute('role','listbox');panel.setAttribute('aria-label',labelFor(field));panel.innerHTML=[...field.options].map(o=>`<button type="button" role="option" aria-selected="${o.selected}" data-value="${esc(o.value)}" ${o.disabled?'disabled':''}><span>${esc(o.textContent)}</span>${o.selected?'<span class="option-check">✓</span>':''}</button>`).join('');trigger.parentElement.append(panel);panel.setAttribute('popover','manual');if(panel.showPopover)panel.showPopover();trigger.setAttribute('aria-expanded','true');active={panel,trigger,at:performance.now()};place(panel,trigger);panel.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const b=e.target.closest('[data-value]');if(b)choose(field,b.dataset.value,trigger)});(panel.querySelector('[aria-selected=true]')||panel.querySelector('button'))?.focus({preventScroll:true});}
function showCalendar(field,trigger){closePicker();const panel=document.createElement('div');panel.className='picker-popover calendar-popover';panel.id=trigger.getAttribute('aria-controls');panel.setAttribute('role','dialog');panel.setAttribute('aria-label',labelFor(field));let shown=field.value?parse(field.value):new Date(),mode='days',yearBase=shown.getFullYear()-4;trigger.parentElement.append(panel);panel.setAttribute('popover','manual');if(panel.showPopover)panel.showPopover();trigger.setAttribute('aria-expanded','true');active={panel,trigger,at:performance.now()};
const draw=()=>{const y=shown.getFullYear(),m=shown.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,today=localKey(new Date());let body='';if(mode==='days'){body=`<div class="calendar-weekdays">${['Pt','Sa','Ça','Pe','Cu','Ct','Pz'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const d=new Date(y,m,1-offset+i),v=localKey(d);return `<button type="button" data-date="${v}" class="${d.getMonth()!==m?'other-month ':''}${v===field.value?'picked ':''}${v===today?'calendar-today':''}" aria-label="${esc(d.toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'}))}" ${field.min&&v<field.min||field.max&&v>field.max?'disabled':''}>${d.getDate()}</button>`}).join('')}</div>`;}else if(mode==='months'){body=`<div class="calendar-months">${Array.from({length:12},(_,i)=>`<button type="button" data-month="${i}" class="${i===m?'picked':''}">${new Date(y,i,1).toLocaleDateString('tr-TR',{month:'short'})}</button>`).join('')}</div>`;}else{body=`<div class="calendar-months">${Array.from({length:12},(_,i)=>`<button type="button" data-year="${yearBase+i}" class="${yearBase+i===y?'picked':''}">${yearBase+i}</button>`).join('')}</div>`;}
panel.innerHTML=`<div class="calendar-head"><button type="button" data-cal="prev" aria-label="Önceki ${mode==='days'?'ay':'yıl'}">‹</button><div><button type="button" data-cal="months">${shown.toLocaleDateString('tr-TR',{month:'long'})}</button><button type="button" data-cal="years">${mode==='years'?`${yearBase}–${yearBase+11}`:y}</button></div><button type="button" data-cal="next" aria-label="Sonraki ${mode==='days'?'ay':'yıl'}">›</button></div>${body}<div class="calendar-shortcuts"><button type="button" data-date="${today}">Bugün</button><button type="button" data-date="${localKey(new Date(new Date().setDate(new Date().getDate()+1)))}">Yarın</button>${!field.required?'<button type="button" data-date="">Temizle</button>':''}</div>`;place(panel,trigger);};
panel.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-date')){choose(field,b.dataset.date,trigger);return}if(b.hasAttribute('data-month')){shown=new Date(shown.getFullYear(),Number(b.dataset.month),1);mode='days'}else if(b.hasAttribute('data-year')){shown=new Date(Number(b.dataset.year),shown.getMonth(),1);mode='months'}else if(b.dataset.cal==='months')mode='months';else if(b.dataset.cal==='years')mode='years';else if(b.dataset.cal){const delta=b.dataset.cal==='prev'?-1:1;if(mode==='years')yearBase+=12*delta;else shown=new Date(shown.getFullYear()+(mode==='months'?delta:0),shown.getMonth()+(mode==='days'?delta:0),1);}draw();});draw();(panel.querySelector('.picked')||panel.querySelector('.calendar-today')||panel.querySelector('button'))?.focus({preventScroll:true});}
export function enhanceControls(root=document){for(const field of root.querySelectorAll('select,input[type=date],input[type=time]')){if(field.dataset.enhanced)continue;field.dataset.enhanced='true';if(field.type==='time'){field.type='text';field.inputMode='numeric';field.placeholder='--:--';field.pattern='([01][0-9]|2[0-3]):[0-5][0-9]';field.maxLength=5;field.classList.add('time-input');field.title='24 saat biçimi, örnek: 09:30';field.addEventListener('input',()=>{const digits=field.value.replace(/\D/g,'').slice(0,4);if(digits.length>2&&!field.value.includes(':'))field.value=digits.slice(0,2)+':'+digits.slice(2);});field.addEventListener('blur',()=>{const v=field.value.trim().replace('.',':');if(/^\d{1,2}$/.test(v))field.value=v.padStart(2,'0')+':00';else if(/^\d{1,2}:\d{1,2}$/.test(v))field.value=v.split(':').map(x=>x.padStart(2,'0')).join(':');field.dispatchEvent(new Event('input',{bubbles:true}));});continue;}
const wrap=document.createElement('div');wrap.className='app-control';wrap._field=field;field.before(wrap);wrap.append(field);field.classList.add('picker-source');field.tabIndex=-1;field.setAttribute('aria-hidden','true');const trigger=document.createElement('button');trigger.type='button';trigger.className='control-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',labelFor(field));trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-haspopup',field.tagName==='SELECT'?'listbox':'dialog');trigger.setAttribute('aria-controls','picker-'+(++count));trigger.innerHTML=`${field.type==='date'?calendarIcon:''}<span class="control-value"></span>${chevron}`;wrap.append(trigger);trigger.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(active?.trigger===trigger){closePicker(true);return}if(field.tagName==='SELECT')showOptions(field,trigger);else showCalendar(field,trigger);});trigger.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();trigger.click();}});field.addEventListener('change',refreshControls);field.addEventListener('invalid',e=>{e.preventDefault();trigger.focus();trigger.classList.add('invalid');trigger.addEventListener('click',()=>trigger.classList.remove('invalid'),{once:true});});}refreshControls();}
document.addEventListener('pointerdown',e=>{if(active&&!active.panel.contains(e.target)&&!active.trigger.contains(e.target))closePicker();});
document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closePicker(true);return}if(e.key==='Tab'){closePicker();return}if(['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...active.panel.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);let delta=['ArrowUp','ArrowLeft'].includes(e.key)?-1:1;if(active.panel.classList.contains('calendar-popover')&&['ArrowDown','ArrowUp'].includes(e.key)&&document.activeElement?.hasAttribute('data-date'))delta=e.key==='ArrowDown'?7:-7;const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+delta+buttons.length)%buttons.length;buttons[next]?.focus({preventScroll:true});}else if(e.key.length===1&&active.panel.classList.contains('select-popover')){const b=[...active.panel.querySelectorAll('button')].find(b=>b.textContent.trim().toLocaleLowerCase('tr').startsWith(e.key.toLocaleLowerCase('tr')));b?.focus({preventScroll:true});}},true);
window.addEventListener('resize',()=>closePicker());
document.addEventListener('scroll',e=>{if(active&&performance.now()-active.at>150&&!active.panel.contains(e.target))closePicker();},true);
const observer=new MutationObserver(records=>{if(records.some(r=>r.type==='childList'&&[...r.addedNodes].some(n=>n.nodeType===1)))enhanceControls();if(records.some(r=>r.type==='attributes'))refreshControls();});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled']});
